// Las fechas llegan de la API en hora UTC del servidor, sin zona
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fecha = d => d ? new Date(String(d).endsWith('Z') ? d : d + 'Z').toLocaleString('es-ES', { timeZone: 'Europe/Madrid', dateStyle: 'short', timeStyle: 'short' }) : '—';
const idioma = l => ({ es: 'castellano', ca: 'catalán' }[l] || '—');
const fila = (k, v) => `<tr><td style="padding:4px 12px 4px 0;color:#64748b">${k}</td><td style="padding:4px 0;color:#0f172a">${v}</td></tr>`;
const ficha = c => `<table style="border-collapse:collapse;font-size:14px">
  ${fila('Negocio', `<b>${esc(c.name)}</b>${c.city ? ' · ' + esc(c.city) : ''}`)}
  ${fila('Contacto', esc(c.adminName) || '—')}
  ${fila('Email', c.adminEmail ? `<a href="mailto:${esc(c.adminEmail)}">${esc(c.adminEmail)}</a>` : '—')}
  ${fila('Teléfono', esc(c.phone) || '—')}
  ${fila('Idioma', idioma(c.language))}
  ${fila('Email verificado', c.emailVerified ? 'sí' : 'no')}
  ${fila('Registro', fecha(c.createdAt))}
  ${fila('Fin de la prueba', c.trialEndsAt ? fecha(c.trialEndsAt) : 'cliente de pago')}
</table>`;
const plantilla = (titulo, cuerpo) => `<div style="font-family:Arial,sans-serif;max-width:640px;color:#0f172a">
  <h2 style="margin:0 0 12px">${titulo}</h2>${cuerpo}
  <p style="margin-top:24px;font-size:12px;color:#94a3b8">Alerta interna de PedidAI generada por n8n.</p></div>`;

const s = $input.first().json;
const lista = (titulo, items, nota) => items && items.length
  ? `<h3 style="margin:20px 0 6px">${titulo} (${items.length})</h3>${nota ? `<p style="margin:0 0 8px;color:#64748b;font-size:13px">${nota}</p>` : ''}` +
    items.map(c => `<div style="border:1px solid #e2e8f0;border-radius:8px;padding:10px;margin-bottom:8px">${ficha(c)}</div>`).join('')
  : '';
const numeros = `<table style="border-collapse:collapse;font-size:14px">
  ${fila('Registros nuevos', `<b>${s.newCompanies.length}</b>`)}
  ${fila('Líneas de albarán leídas', s.invoiceLinesRead)}
  ${fila('Pedidos creados', s.ordersCreated)}
  ${fila('Clientes en total', `${s.totalClients} (${s.inTrial} en prueba · ${s.paid} de pago · ${s.trialOver} con la prueba acabada)`)}
</table>`;
const secciones = [
  lista('Registros nuevos', s.newCompanies),
  lista('Pruebas que acaban en 3 días o menos', s.trialsEndingSoon, 'Buen momento para llamar y ofrecer el plan.'),
  lista('Pruebas acabadas sin contratar', s.trialsExpired, 'Su cuenta está suspendida hasta que contraten.'),
  lista('Datos que se borrarán en menos de 7 días', s.deletionSoon, 'Último aviso antes del borrado automático (30 días tras la prueba).'),
].join('');
const hoy = new Date().toLocaleDateString('es-ES', { timeZone: 'Europe/Madrid', day: 'numeric', month: 'long' });
const html = plantilla(`Resumen de PedidAI · últimas ${s.hours} h`, numeros + (secciones || '<p style="margin-top:16px">Sin novedades en registros ni pruebas.</p>'));
const n = s.newCompanies.length;
return [{ json: { subject: `PedidAI · Resumen del ${hoy}: ${n} ${n === 1 ? 'registro nuevo' : 'registros nuevos'}`, html } }];
